(()=>{'use strict';const $=(s,r=document)=>r.querySelector(s),key='pcp-saved-v1',money=n=>n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}),fixed=n=>n.toFixed(2);let searchIndex;
 const index=()=>searchIndex||(searchIndex=fetch('/data/search-index.json').then(r=>{if(!r.ok)throw Error('Search is temporarily unavailable.');return r.json()}));
 const read=()=>{try{const data=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(data)?data.filter(x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,160}$/.test(x)).slice(0,100):[]}catch{return[]}};
 const write=ids=>{try{localStorage.setItem(key,JSON.stringify([...new Set(ids)].slice(0,100)));return true}catch{return false}};
 const status=text=>{const el=$('[data-saved-status]');if(el)el.textContent=text};
 function paintSave(){const ids=read();document.querySelectorAll('[data-save-id]').forEach(b=>{const saved=ids.includes(b.dataset.saveId);b.setAttribute('aria-pressed',String(saved));b.textContent=saved?'Saved to your list':'Save to your list'})}
 document.querySelectorAll('[data-save-id]').forEach(b=>b.addEventListener('click',()=>{const ids=read(),id=b.dataset.saveId;if(!ids.includes(id)&&ids.length>=100){status('Your list holds up to 100 items. Remove an item to add another.');return}const next=ids.includes(id)?ids.filter(x=>x!==id):ids.concat(id);status(write(next)?'List updated on this device.':'Your browser could not save this list.');paintSave()}));paintSave();
 const saved=$('[data-saved-list]');if(saved){const render=async()=>{try{const rows=await index(),ids=read(),items=rows.filter(x=>ids.includes(x.id));saved.replaceChildren();for(const row of items){const li=document.createElement('li'),a=document.createElement('a'),remove=document.createElement('button');a.href=row.url;a.textContent=row.title;remove.type='button';remove.className='button secondary';remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+row.title);remove.addEventListener('click',()=>{if(write(read().filter(id=>id!==row.id)))render();else status('Your browser could not update the list.')});li.append(a,remove);saved.append(li)}if(!items.length)status('No saved items on this device yet. Use Save to your list on a guide, phone or product page.')}catch(e){status(e.message)}};render();$('[data-clear-saved]')?.addEventListener('click',()=>{if(write([])){render();status('Saved items cleared.')}else status('Your browser could not clear the list.')})}
 const normalize=s=>s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g,'');
 const search=$('[data-publication-search]');if(search){const input=$('input',search),result=$('[data-search-results]'),message=$('[data-search-status]');search.addEventListener('submit',async e=>{e.preventDefault();message.textContent='Searching…';try{const q=normalize(input.value);if(!q){message.textContent='Enter a product, guide or tool name.';result.replaceChildren();return}const rows=await index(),matches=rows.map(row=>({row,exact:normalize(row.title)===q||(row.aliases||[]).some(a=>normalize(a)===q),hit:normalize(row.title+' '+(row.aliases||[]).join(' ')).includes(q)})).filter(x=>x.hit).sort((a,b)=>Number(b.exact)-Number(a.exact)).slice(0,40);result.replaceChildren();for(const {row}of matches){const li=document.createElement('li'),a=document.createElement('a'),p=document.createElement('p');a.href=row.url;a.textContent=row.title;p.textContent=row.kind;li.append(a,p);result.append(li)}message.textContent=matches.length?matches.length+' results shown.':'No matching result. Try a model code or a shorter name.'}catch(e){message.textContent=e.message}})}
 for(const form of document.querySelectorAll('[data-planning]'))form.addEventListener('submit',e=>{e.preventDefault();const output=$('output',form);try{const v={};for(const el of form.elements)if(el.name)v[el.name]=el.type==='checkbox'?el.checked:el.value;const r=PCPPlanning[form.dataset.planning](v),currency=v.currency==='CAD'?'CAD':'USD';const text={electricity:()=>`${fixed(r.kWh)} kWh per day. Daily: ${money(r.daily)} ${currency}. 30 days: ${money(r.monthly)} ${currency}. 365 days: ${money(r.annual)} ${currency}.`,platform:()=>`Option A: ${money(r.a)} ${currency}. Option B: ${money(r.b)} ${currency}. B ${r.difference>=0?'costs more by':'costs less by'} ${money(Math.abs(r.difference))} ${currency}.`,display:()=>`${fixed(r.ppi)} pixels per inch. Active rectangle: ${fixed(r.width)} × ${fixed(r.height)} inches (${fixed(r.width*2.54)} × ${fixed(r.height*2.54)} cm).`,recording:()=>`${fixed(r.gb)} GB, or ${fixed(r.gib)} GiB, including your allowance.`,ai:()=>`Weight estimate: ${fixed(r.weights)} GiB. With your runtime and KV budgets: ${fixed(r.total)} GiB. Fit and speed are not certified.`,frametime:()=>`${fixed(r.frame)} ms per frame; ${fixed(r.refresh)} ms per refresh interval. Neither is measured input latency.`,lanes:()=>`M2_3: ${r.m2_3}. PCI_E2: ${r.pci_e2}. M2_2: ${r.m2_2}.`};output.textContent=text[form.dataset.planning]();output.removeAttribute('data-error')}catch(err){output.textContent=err.message;output.dataset.error='true'}});
})();
